try{const saved=JSON.parse(localStorage.getItem(PROGRESS_KEY)||'null');const known=new Set([...BODIES,...MOONS].map(p=>p.id));if(Array.isArray(saved?.visited))for(const id of saved.visited)if(known.has(id))state.visited.add(id);if(SHIP_COLORS.some(c=>c.id===saved?.shipColor))state.shipColor=saved.shipColor;if(saved?.moonMode===false)state.moonMode=false;if(Array.isArray(saved?.played))for(const id of saved.played)if(known.has(id))state.played.add(id);if(Number.isFinite(saved?.quizStars))state.quizStars=Math.max(0,Math.min(999,Math.floor(saved.quizStars)));if(Number.isFinite(saved?.quizCorrect))state.quizCorrect=Math.max(0,Math.floor(saved.quizCorrect));}catch{}
