function paintGraffiti(){const canvas=document.createElement('canvas');canvas.width=512;canvas.height=256;const ctx=canvas.getContext('2d');ctx.translate(252,130);ctx.rotate(-.065);ctx.transform(1,0,-.16,1,0,0);const colors=['#ff76ba','#ffde71','#79e4e2','#ba95ff','#ff9e6e'];for(let i=0;i<21;i++){ctx.fillStyle=colors[i%5];ctx.beginPath();ctx.arc(Math.sin(i*5.2)*216,Math.cos(i*3.1)*67,3+i%5,0,Math.PI*2);ctx.fill();}ctx.font='italic 900 106px "Arial Black",sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.lineJoin='round';ctx.strokeStyle='#202642';ctx.lineWidth=22;ctx.strokeText('SOFIA',0,0);ctx.strokeStyle='#fff8e7';ctx.lineWidth=11;ctx.strokeText('SOFIA',0,0);const letters='SOFIA',widths=[...letters].map(l=>ctx.measureText(l).width),total=widths.reduce((a,b)=>a+b,0);let x=-total/2;ctx.textAlign='left';for(let i=0;i<letters.length;i++){ctx.fillStyle=colors[i];ctx.fillText(letters[i],x,0);x+=widths[i];}ctx.strokeStyle='#79e4e2';ctx.lineWidth=7;ctx.beginPath();ctx.moveTo(-177,66);ctx.lineTo(183,51);ctx.stroke();return canvas;}
const sofiaGraffiti=paintGraffiti();
function rewardMessage(before,after){const messages=[];if(!before.graffiti&&after.graffiti)messages.push('Kult, Sofia! Du har besøkt to forskjellige planeter! Nå har raketten fått tøff graffiti med navnet ditt!');if(!before.paint&&after.paint)messages.push('Fantastisk, Sofia! Fire planetbesøk! Raketten din har fått en ny lilla og rosa farge!');if(!before.palette&&after.palette)messages.push('Seks planetbesøk, Sofia! Nå kan du velge rakettfarge selv. Fargeknappene står hjemme på jorda!');if(!before.rainbow&&after.rainbow)messages.push('Hurra, Sofia! Du har oppdaget alle reisemålene! Nå lager raketten din regnbuer!');if(!before.moonMode&&after.moonMode)messages.push('Helt utrolig, Sofia! Du har besøkt alle planetene! Nå er månemodus åpen: månene går i bane rundt planetene sine, og du kan reise til dem.');if(!before.gold&&after.gold)messages.push('Du har besøkt alle månene, Sofia! Raketten din er blitt av rent gull, med en ekte diamant på toppen og et spor av gullmynter etter seg!');return messages.join(' ');}
