function updateBoost(dt){state.boostHold=Math.max(0,state.boostHold-dt);state.boostFlash=Math.max(0,state.boostFlash-dt);state.speed=relaxSpeed(state.speed,dt,state.boostHold);const desired=Math.min(4.2,Math.max(0,state.speed-1)*1.85)+(state.boostFlash>0?.45:0);state.rocketOffset+=(desired-state.rocketOffset)*(1-Math.exp(-dt*(desired>state.rocketOffset?9:2.5)));$('boost-callout').hidden=state.boostFlash<=0;}
