function updatePassport(){$('passport').textContent=moonModeOn()?`✦ ${bodiesVisited()} / 10 · 🌙 ${rewards.moons} / ${MOONS.length}`:`✦ ${bodiesVisited()} / 10 oppdaget`;const items=[];if(rewards.graffiti)items.push('★ SOFIA-graffiti');if(rewards.paint)items.push('★ Stjernerakett');if(rewards.palette)items.push('🎨 Fargevalg');if(rewards.rainbow)items.push('🌈 Regnbuespor');if(rewards.moonMode)items.push('🌙 Månemodus');if(rewards.gold)items.push('💎 Gullrakett');$('rocket-rewards').textContent=items.join(' · ');$('rocket-rewards').hidden=!items.length;$('inside-rewards').textContent=items.join(' · ');$('inside-rewards').hidden=!items.length;$('inside-progress').textContent=insideProgress();$('rewards-info').textContent=`${rewards.planets} av 8 planetbesøk og ${rewards.moons} av ${MOONS.length} måner. Graffiti etter 2, nye farger etter 4, eget fargevalg etter 6, månemodus når alle 8 planetene er besøkt og gullrakett med diamant og myntspor når alle månene er oppdaget. Jorda teller som hjemme. Pluto teller som et planetbesøk i spillet, sola som et eget reisemål.`;renderColorPicker();renderMoonToggle();}
