// The colour picker opens with the sixth planet visit and lives on the home console.
function renderColorPicker(){const box=$('color-choice'),swatches=$('color-swatches');box.hidden=!rewards.palette;if(!rewards.palette){swatches.replaceChildren();return;}const current=shipPaint(rewards,state.shipColor);swatches.replaceChildren();for(const c of shipColorsFor(rewards)){const btn=document.createElement('button');btn.className='swatch'+(c.id===current.id?' selected':'');btn.type='button';btn.style.background=`linear-gradient(145deg,${c.body} 52%,${c.accent} 52%)`;btn.setAttribute('aria-label',c.name);btn.setAttribute('aria-pressed',String(c.id===current.id));btn.title=c.name;btn.onclick=()=>{state.shipColor=c.id;saveProgress();renderColorPicker();tone(430,.06);speak(c.name);};swatches.append(btn);}}
