function updateSettings(){for(const [id,key]of [['hint-toggle','hints'],['voice-toggle','voice'],['motion-toggle','reduced']]){const b=$(id);b.textContent=state[key]?'På':'Av';b.classList.toggle('on',state[key]);b.setAttribute('aria-pressed',String(state[key]));}}
function home(withMessage=false,preserveSpeech=false){state.mode='home';resetFx();state.location=earth;state.target=null;clearFlyby();state.paused=false;state.speed=1;state.boostHold=0;state.boostFlash=0;state.rocketOffset=0;$('boost-callout').hidden=true;state.angle=0;state.wordLocked=false;wordDelay=0;showConsole('home');$('pause').hidden=true;$('world-hint').hidden=true;$('scene-caption').hidden=true;$('countdown').hidden=true;$('app').classList.remove('boosted');for(const id of ['pause-modal','map-modal','system-modal'])$(id).hidden=true;title('HER BEGYNNER EVENTYRET','Hjemme på jorda','Raketten er klar. Hvor skal vi reise?','⌂ Din egen lille rombase');scene.setAttribute('aria-label','Sofia ved det brune huset sitt i skogen. Dra for å se deg rundt.');if(!preserveSpeech)gameAudio.stopSpeech();if(withMessage){notify('Trygt hjemme, Sofia! En ny rakett står klar.');if(!preserveSpeech)speak('Trygt hjemme, Sofia! En ny rakett står klar.');}}
