function tick(now){if(!renderer)return;const dt=Math.min((now-lastFrame)/1000,1);lastFrame=now;if(!state.paused){state.clock+=dt;if(state.mode==='launch'){const prev=Math.ceil(3-state.launchTime);state.launchTime+=dt;const n=Math.ceil(3-state.launchTime);if(n!==prev&&n>0)gameAudio.effect('countdown');if(state.launchTime>=2.6&&state.launchTime-dt<2.6)gameAudio.effect('launch');$('countdown').textContent=n>0?String(n):'AVGANG!';$('countdown').classList.toggle('go',n<=0);if(state.launchTime>=3.7){state.mode='flight';$('countdown').hidden=true;title('UTE PÅ ROMFERD',`Mot ${state.target.name}!`,'Bokstavkraft gir ekstra fart.',state.target.type);scene.setAttribute('aria-label',`Raketten flyr fra ${state.origin.name} til ${state.target.name}.`);}}
 if(state.mode==='flight'){state.elapsed+=dt*state.speed;updateBoost(dt);updateFlybys(dt);updateFlightFx(dt);state.starTravel+=dt*(2+state.speed*5);updateFlight();if(state.elapsed>=state.total)arrive();}if(wordDelay>0){wordDelay-=dt;if(wordDelay<=0&&['flight','launch'].includes(state.mode))newWord();}if(state.mode==='arrival')state.arrivalTime+=dt;if(state.mode==='play')updatePlay(dt);if(state.mode==='quiz')updateQuiz(dt);updateFx(dt);if(state.mode==='sun'){state.sunTime+=dt;if(state.sunTime>1.6&&!state.rescueSound){state.rescueSound=true;gameAudio.effect('rescue');}if(state.sunTime>7){$('sun-flash').classList.remove('active');home(true,true);}}}
 gameAudio.update();const t=state.clock;if(state.mode==='home')homeScene(t);else if(state.mode==='inside')insideScene(t);else if(state.mode==='launch'&&state.origin.id==='earth')homeScene(t,Math.pow(Math.max(0,state.launchTime-2.5),2)*6);else if(state.mode==='launch'||state.mode==='flight')flightScene(t);else if(state.mode==='arrival')arrivalScene(t);else if(state.mode==='play')playScene(t);else if(state.mode==='quiz')quizScene(t);else if(state.mode==='sun')sunScene(t);drawSparks();updateSpace();renderer.end?.();requestAnimationFrame(tick);}
